import { createStore } from "../../../shared/lib/store.js";

export function createCompanionStore(model) {
    const store = createStore({ activeId: model.activeSportId, liveOnly: false, revision: 0 });
    const ids = model.sports.map((sport) => sport.id);
    return {
        store,
        selectSport(id) {
            store.setState((state) => (state.activeId === id ? state : { activeId: id, revision: state.revision + 1 }));
        },
        moveSelection(id, key) {
            const index = ids.indexOf(id);
            const next = key === "ArrowRight" ? (index + 1) % ids.length : key === "ArrowLeft" ? (index + ids.length - 1) % ids.length : key === "Home" ? 0 : key === "End" ? ids.length - 1 : -1;
            return next < 0 ? null : ids[next];
        },
        toggleLiveOnly() {
            store.setState((state) => ({ liveOnly: !state.liveOnly, revision: state.revision + 1 }));
        },
    };
}
