import { memo } from "preact/compat";
import { icons } from "./generated/icons.js";
import { t } from "./lib/i18n.js";

const iconNames = Object.keys(icons);

function sportIcon(index) {
    return icons[iconNames[(index * 7) % iconNames.length]];
}

export const SportTab = memo(function SportTab({ sport, index, selected, onSelect, onKeyDown }) {
    return (
        <button class="scp-tab" type="button" role="tab" id={`scp-tab-${sport.id}`} aria-selected={selected ? "true" : "false"} aria-controls="scp-panel" tabIndex={selected ? 0 : -1} data-tone={sport.tone} onClick={() => onSelect(sport.id)} onKeyDown={(event) => onKeyDown(event, sport.id)}>
            <svg class="scp-tab__icon" viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
                <path d={sportIcon(index)} fill="none" stroke="currentColor" stroke-width="1.4" />
            </svg>
            {sport.label}
        </button>
    );
});

export const ResultRow = memo(function ResultRow({ fixture }) {
    return (
        <li class="scp-row" data-state={fixture.state}>
            <a class="scp-row__link" href={fixture.href} aria-label={fixture.label}>
                <span class="scp-row__status">{fixture.status}</span>
                <span class="scp-row__team scp-row__team--home" data-leader={fixture.leader === "home" ? "true" : "false"}>{fixture.home.name}</span>
                <span class="scp-row__abbr">{fixture.home.shortName}</span>
                <span class="scp-row__score">{fixture.score}</span>
                <span class="scp-row__abbr">{fixture.away.shortName}</span>
                <span class="scp-row__team scp-row__team--away" data-leader={fixture.leader === "away" ? "true" : "false"}>{fixture.away.name}</span>
            </a>
        </li>
    );
});

export const LeagueGroup = memo(function LeagueGroup({ league, fixtures, tone }) {
    return (
        <section class="scp-group" data-tone={tone} aria-labelledby={`scp-league-${league.id}`}>
            <h3 class="scp-group__title" id={`scp-league-${league.id}`}>{league.name}</h3>
            <ul class="scp-list">
                {fixtures.map((fixture) => (
                    <ResultRow key={fixture.id} fixture={fixture} />
                ))}
            </ul>
        </section>
    );
});

export const LiveFilter = memo(function LiveFilter({ pressed, count, onToggle }) {
    return (
        <button class="scp-filter" type="button" aria-pressed={pressed ? "true" : "false"} title={t("companion.liveCount", { count })} onClick={onToggle}>
            {t("companion.liveOnly")}
        </button>
    );
});

export const Legend = memo(function Legend() {
    return (
        <ul class="scp-legend" aria-label={t("companion.legend")}>
            {["live", "finished", "scheduled"].map((state) => (
                <li class="scp-legend__item" key={state} data-state={state.toUpperCase()}>
                    {t(`companion.legend.${state}`)}
                </li>
            ))}
        </ul>
    );
});
