import { useMemo } from "preact/hooks";
import { useParsedData, useWidgetEvents } from "../../shared/lib/lifecycle.js";
import { useStore } from "../../shared/lib/store.js";
import { createCompanionStore } from "./lib/state.js";
import { groupByLeague, normalizeCompanion } from "./lib/normalize.js";
import { t } from "./lib/i18n.js";
import { Legend, LeagueGroup, LiveFilter, SportTab } from "./components.js";

export const TAG = "np-scores-companion";

function Companion({ model }) {
    const controller = useMemo(() => createCompanionStore(model), [model]);
    const { store } = controller;
    const activeId = useStore(store, (state) => state.activeId);
    const liveOnly = useStore(store, (state) => state.liveOnly);
    const revision = useStore(store, (state) => state.revision);
    const ref = useWidgetEvents(TAG, revision);
    const sport = model.sports.find((candidate) => candidate.id === activeId);
    const groups = groupByLeague(sport, liveOnly);

    function onKeyDown(event, id) {
        const next = controller.moveSelection(id, event.key);
        if (!next)
            return;
        event.preventDefault();
        controller.selectSport(next);
        ref.current?.querySelector(`#scp-tab-${next}`)?.focus();
    }

    return (
        <div class="scp-root" data-variant={model.variant} ref={ref}>
            <header class="scp-header">
                <h2 class="scp-title">{t("companion.title")}</h2>
                <LiveFilter pressed={liveOnly} count={sport.liveCount} onToggle={controller.toggleLiveOnly} />
            </header>
            <div class="scp-tabs" role="tablist" aria-label={t("companion.sports")}>
                {model.sports.map((candidate, index) => (
                    <SportTab key={candidate.id} sport={candidate} index={index} selected={candidate.id === activeId} onSelect={controller.selectSport} onKeyDown={onKeyDown} />
                ))}
            </div>
            <div class="scp-panel" id="scp-panel" role="tabpanel" aria-labelledby={`scp-tab-${activeId}`}>
                {groups.length ? groups.map((group) => <LeagueGroup key={group.league.id} league={group.league} fixtures={group.fixtures} tone={sport.tone} />) : <p class="scp-empty">{t("companion.empty")}</p>}
            </div>
            <footer class="scp-footer">
                <Legend />
                <a class="scp-all" href="/sport/ergebnisse">{t("companion.all")}</a>
            </footer>
        </div>
    );
}

export function Widget({ dataJson }) {
    const data = useParsedData(dataJson);
    const model = useMemo(() => (data ? normalizeCompanion(data) : null), [data]);
    return model ? <Companion model={model} /> : null;
}
