import { assertValid } from "../../../shared/lib/validate.js";
import { formatTime } from "../../../shared/lib/format.js";
import { schemas } from "./schema.js";
import { formatScore, leader } from "./scoring.js";
import { t } from "./i18n.js";

function statusText(fixture, kickoff) {
    if (fixture.state === "LIVE")
        return t("companion.minute", { minute: fixture.minute });
    if (fixture.state === "FINISHED")
        return t("companion.finished");
    return t("companion.scheduled", { time: formatTime(kickoff) });
}

function normalizeFixture(sport, fixture) {
    const kickoff = Date.parse(fixture.kickoff);
    const score = formatScore(sport.mode, fixture.score);
    const status = statusText(fixture, kickoff);
    return {
        id: fixture.id,
        league: fixture.league,
        state: fixture.state,
        status,
        score,
        leader: leader(sport.mode, fixture.score),
        home: fixture.home,
        away: fixture.away,
        href: `/sport/${sport.id}/${fixture.id}`,
        label: t("companion.rowLabel", { home: fixture.home.name, away: fixture.away.name, score, status }),
    };
}

export function normalizeCompanion(raw) {
    assertValid(schemas, "ResultsCompanion", raw);
    const sports = raw.sports.map((sport) => {
        const fixtures = sport.fixtures.map((fixture) => normalizeFixture(sport, fixture));
        return {
            id: sport.id,
            label: sport.label,
            tone: sport.tone,
            leagues: sport.leagues,
            fixtures,
            liveCount: fixtures.filter((fixture) => fixture.state === "LIVE").length,
        };
    });
    return { id: raw.id, variant: raw.variant, now: Date.parse(raw.now), activeSportId: raw.activeSportId, sports };
}

export function groupByLeague(sport, liveOnly) {
    const fixtures = liveOnly ? sport.fixtures.filter((fixture) => fixture.state === "LIVE") : sport.fixtures;
    return sport.leagues
        .map((league) => ({ league, fixtures: fixtures.filter((fixture) => fixture.league === league.id) }))
        .filter((group) => group.fixtures.length > 0);
}
