import { t } from "./i18n.js";

const formatters = {
    goals: (score) => `${score.home}:${score.away}`,
    points: (score) => `${score.home}:${score.away}`,
    sets: (score) => (score.sets || []).map((set) => t("companion.score.sets", { home: set.home, away: set.away })).join(" "),
    race: (score) => t("companion.score.race", { position: score.position }),
};

export function formatScore(mode, score) {
    if (!score)
        return t("companion.score.pending");
    return (formatters[mode] || formatters.goals)(score);
}

export function leader(mode, score) {
    if (!score || mode === "race")
        return null;
    if (mode === "sets") {
        let home = 0;
        let away = 0;
        for (const set of score.sets || []) {
            if (set.home > set.away)
                home++;
            else if (set.away > set.home)
                away++;
        }
        return home === away ? null : home > away ? "home" : "away";
    }
    return score.home === score.away ? null : score.home > score.away ? "home" : "away";
}
